    'about.historyText1': 'Founded in 2020, NTDM Vettrack has been at the forefront of veterinary innovation in Rwanda. Our journey began with a simple vision: to revolutionize animal health management through technology and expert care.',
    'about.historyText2': "Over the years, we've grown from a small local clinic to a comprehensive animal health service provider, thanks to our commitment to excellence and our passionate team of skilled veterinarians and technologists.",
    'about.missionText': 'To transform livestock health and farm management through innovative, technology driven solutions that enable smarter, more sustainable, and data driven farming with AI & IoT.',
    'about.visionText': "To become Africa's leading smart animal health and management service, combining IoT and Artificial Intelligence to build a healthier, more sustainable livestock sector. We envision a future where every farmer in Rwanda and beyond benefits from digital veterinary access, real-time disease report and prediction, and a connected agricultural marketplace that drives productivity and strengthens public health.",
