    'province.western': 'Iburengerazuba',
    'about.historyText1': "NTDM Vettrack yashinzwe mu 2020, kandi kuva icyo gihe iri ku isonga mu guhanga udushya mu buvuzi bw'amatungo mu Rwanda. Urugendo rwacu rwatangiranye n'icyerekezo cyoroshye: guhindura imicungire y'ubuzima bw'amatungo dukoresheje ikoranabuhanga n'ubumenyi bw'inzobere.",
    'about.historyText2': "Mu myaka ishize, twavuye ku ivuriro rito ry'aho dutuye tuba utanga serivisi zuzuye z'ubuzima bw'amatungo, kubera umuhate wacu wo gukora neza n'itsinda ryacu ry'abaganga b'amatungo n'abahanga mu ikoranabuhanga bakunda umurimo wabo.",
    'about.missionText': "Guhindura ubuzima bw'amatungo n'imicungire ya farumu binyuze mu bisubizo bishya bishingiye ku ikoranabuhanga, bituma ubworozi burushaho kuba ubw'ubwenge, burambye kandi bushingiye ku makuru, hakoreshejwe AI na IoT.",
    'about.visionText': "Kuba serivisi ya mbere muri Afurika mu buzima n'imicungire y'amatungo hakoreshejwe ubwenge, duhuza IoT n'ubwenge bw'ubukorano (AI) kugira ngo twubake urwego rw'ubworozi rufite ubuzima bwiza kandi rurambye. Turabona ejo hazaza aho buri mworozi mu Rwanda n'ahandi abona serivisi z'abaganga b'amatungo binyuze mu ikoranabuhanga, raporo n'iteganya ry'indwara ako kanya, n'isoko ry'ubuhinzi rihuza abantu rizamura umusaruro kandi rikomeza ubuzima rusange.",
    'about.cattleAlt': 'Inka zirisha kuri farumu',
